import { ELAPSED_MAX_MS, MOVES_MAX } from '../game.ts';

export interface Result { moves: number; elapsedMs: number }
export interface Match { players: [number, number]; code: string; results: Result[] }
export interface TournamentState { names: string[]; matches: Match[] }

export function normalizeName(name: string): string {
  return name.trim().replace(/\s+/gu, ' ').normalize('NFC');
}
export function namesError(names: string[]): string {
  if (names.some((name) => Array.from(name).length < 2 || Array.from(name).length > 20))
    return 'Use 2 to 20 characters.';
  if (new Set(names.map((name) => name.toLowerCase())).size !== names.length)
    return 'Each name must be different.';
  return '';
}
export function roundSize(count: number, index: number): number {
  return count === 8 && index < 4 ? 4 : index < count - 2 ? 6 : 8;
}
export function roundName(count: number, index: number): string {
  return roundSize(count, index) === 4 ? 'Quarterfinal' : roundSize(count, index) === 6 ? 'Semifinal' : 'Final';
}
export function winner(match: Match): number | null {
  const [a, b] = match.results;
  if (!a || !b) return null;
  const [first, second] = match.players;
  return a.moves !== b.moves ? (a.moves < b.moves ? first : second)
    : a.elapsedMs !== b.elapsedMs ? (a.elapsedMs < b.elapsedMs ? first : second)
      : Math.min(first, second);
}
export function nextPlayers(t: TournamentState): [number, number] | null {
  const n = t.names.length, i = t.matches.length;
  const opening = n === 4 ? [[0, 3], [1, 2]] : [[0, 7], [3, 4], [2, 5], [1, 6]];
  if (i < opening.length) return opening[i] as [number, number];
  if (i >= n - 1) return null;
  const first = n === 8 && i < 6 ? (i - 4) * 2 : n === 8 ? 4 : 0;
  const a = t.matches[first], b = t.matches[first + 1];
  if (!a || !b) return null;
  const wa = winner(a), wb = winner(b);
  return wa === null || wb === null ? null : [wa, wb];
}
export function isValidResult(value: unknown, size: number): value is Result {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const r = value as Record<string, unknown>;
  return Object.keys(r).sort().join(',') === 'elapsedMs,moves' && typeof r.moves === 'number' &&
    Number.isInteger(r.moves) && r.moves >= size * size / 2 && r.moves <= MOVES_MAX &&
    typeof r.elapsedMs === 'number' && Number.isFinite(r.elapsedMs) && r.elapsedMs >= 0 && r.elapsedMs <= ELAPSED_MAX_MS;
}
import { parseBoardCode } from '../deck.ts';
import { decodeSnapshot } from '../snapshot.ts';
import { isWon } from '../game.ts';
import { namesError, nextPlayers, normalizeName, roundSize, isValidResult, winner } from './model.ts';
import type { Result, TournamentState } from './model.ts';

interface Exchange { tournament: TournamentState | null; snapshot: string | null }
const object = (v: unknown): v is Record<string, unknown> => !!v && typeof v === 'object' && !Array.isArray(v);
function keys(v: Record<string, unknown>, allowed: string[]): string | null {
  return Object.keys(v).find((key) => !allowed.includes(key)) ?? null;
}
export function encodeExchange(data: Exchange): string {
  const tournament = data.tournament && {
    matches: data.tournament.matches.map((m) => ({ code: m.code, players: m.players, results: m.results.map((r) => ({ elapsedMs: r.elapsedMs, moves: r.moves })) })),
    names: data.tournament.names,
  };
  return JSON.stringify({ format: 'neon-pairs/tournament', snapshot: data.snapshot, tournament, version: 1 }, null, 2);
}
export function decodeExchange(text: string): { data?: Exchange; error: string } {
  const fail = (error = 'Invalid tournament.') => ({ error });
  if (new TextEncoder().encode(text).length > 65536) return fail();
  let v: unknown;
  try { v = JSON.parse(text); } catch { return fail(); }
  if (!object(v)) return fail();
  let extra = keys(v, ['format', 'snapshot', 'tournament', 'version']);
  if (extra) return fail(`Unknown field: ${extra}.`);
  if (Object.keys(v).length !== 4 || v.format !== 'neon-pairs/tournament' || v.version !== 1 || !(v.snapshot === null || typeof v.snapshot === 'string')) return fail();
  if (v.tournament === null) return v.snapshot === null ? { data: { tournament: null, snapshot: null }, error: '' } : fail();
  if (!object(v.tournament)) return fail();
  extra = keys(v.tournament, ['matches', 'names']);
  if (extra) return fail(`Unknown field: ${extra}.`);
  const { names, matches } = v.tournament;
  if (Object.keys(v.tournament).length !== 2 || !Array.isArray(names) || ![4, 8].includes(names.length) || !names.every((n) => typeof n === 'string' && n === normalizeName(n)) || namesError(names) || !Array.isArray(matches) || matches.length < 1 || matches.length > names.length - 1) return fail();
  const tournament: TournamentState = { names, matches: [] };
  for (const item of matches) {
    if (!object(item)) return fail();
    extra = keys(item, ['code', 'players', 'results']);
    if (extra) return fail(`Unknown field: ${extra}.`);
    const players = nextPlayers(tournament), parsed = typeof item.code === 'string' ? parseBoardCode(item.code) : null;
    if (Object.keys(item).length !== 3 || !players || !Array.isArray(item.players) || item.players.length !== 2 || item.players[0] !== players[0] || item.players[1] !== players[1] || !parsed || parsed.size !== roundSize(names.length, tournament.matches.length) || tournament.matches.some((m) => m.code === item.code) || !Array.isArray(item.results) || item.results.length > 2) return fail();
    for (const result of item.results) {
      if (object(result)) { extra = keys(result, ['elapsedMs', 'moves']); if (extra) return fail(`Unknown field: ${extra}.`); }
      if (!isValidResult(result, parsed.size)) return fail();
    }
    const previous = tournament.matches.at(-1);
    if (previous && winner(previous) === null) return fail();
    tournament.matches.push({ code: item.code as string, players, results: item.results } as Match);
  }
  const last = tournament.matches.at(-1);
  if (v.snapshot !== null) {
    const game = decodeSnapshot(v.snapshot);
    if (!last || last.results.length === 2 || !game || isWon(game) || game.boardCode !== last.code) return fail();
  }
  return { data: { tournament, snapshot: v.snapshot }, error: '' };
}

import { useEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { formatElapsed } from '../elapsed-time.ts';
import { freshBoardCode } from '../session/fresh-board.ts';
import { Bracket } from './Bracket.tsx';
import { decodeExchange, encodeExchange } from './format.ts';
import { LeaveDialog } from './LeaveDialog.tsx';
import { namesError, nextPlayers, normalizeName, roundName, roundSize, winner } from './model.ts';
import { readTournaments, saveTournaments } from './storage.ts';
import { useTournamentGame } from './use-tournament-game.ts';
import type { BoardFocus } from '../board/Board.tsx';
import type { Result, TournamentState } from './model.ts';
import './tournament.css';

export function Tournament({ back }: { back(): void }) {
  const [count, setCount] = useState(4),
    [drafts, setDrafts] = useState(Array<string>(8).fill(''));
  const [tournament, setTournament] = useState<TournamentState | null>(null);
  const [handoff, setHandoff] = useState(false);
  const [playing, setPlaying] = useState(false),
    [pendingSnapshot, setPendingSnapshot] = useState<string | null>(null);
  const [json, setJson] = useState(''),
    [notice, setNotice] = useState(''),
    [confirm, setConfirm] = useState<(() => void) | null>(null);
  const [saved] = useState(readTournaments),
    [past, setPast] = useState(saved.items),
    [unavailable, setUnavailable] = useState(saved.unavailable);
  const heading = useRef<HTMLHeadingElement>(null),
    board = useRef<BoardFocus>(null);
  useEffect(() => {
    heading.current?.focus();
  }, []);
  const match = tournament?.matches.at(-1),
    champion =
      tournament && match && tournament.matches.length === tournament.names.length - 1
        ? winner(match)
        : null;
  function record(result: Result) {
    if (!tournament || !match) return;
    const updated = {
      ...tournament,
      matches: [
        ...tournament.matches.slice(0, -1),
        { ...match, results: [...match.results, result] },
      ],
    };
    setTournament(updated);
    setHandoff(true);
    setPlaying(false);
    setPendingSnapshot(null);
    const last = updated.matches.at(-1);
    if (updated.matches.length === updated.names.length - 1 && last && winner(last) !== null) {
      const items = [updated, ...past].slice(0, 10);
      setPast(items);
      if (!saveTournaments(items)) setUnavailable(true);
    }
    setNotice(
      `Pair found. All pairs found in ${result.moves} moves and ${formatElapsed(result.elapsedMs)}.`,
    );
  }
  const game = useTournamentGame(record);
  function makeMatch(t: TournamentState): TournamentState {
    const players = nextPlayers(t);
    if (!players) return t;
    let code: string;
    do {
      code = freshBoardCode(roundSize(t.names.length, t.matches.length));
    } while (t.matches.some((m) => m.code === code));
    return { ...t, matches: [...t.matches, { players, code, results: [] }] };
  }
  function startTournament() {
    const names = drafts.slice(0, count).map(normalizeName),
      error = namesError(names);
    if (error) {
      setNotice(error);
      return;
    }
    setTournament(makeMatch({ names, matches: [] }));
    setNotice('Tournament started.');
  }
  function startTurn() {
    if (!match) return;
    game.start(match.code, pendingSnapshot);
    setPendingSnapshot(null);
    setPlaying(true);
    setNotice(`Now playing: ${tournament?.names[match.players[match.results.length] ?? 0]}`);
  }
  function leaveOr(action: () => void) {
    if (tournament && champion === null) setConfirm(() => action);
    else action();
  }
  function load() {
    const decoded = decodeExchange(json);
    if (!decoded.data) {
      setNotice(decoded.error);
      return;
    }
    const data = decoded.data;
    leaveOr(() => {
      game.stop();
      setTournament(data.tournament);
      setHandoff(Boolean(data.tournament?.matches.at(-1)?.results.length === 1 && !data.snapshot));
      setPendingSnapshot(data.snapshot);
      setPlaying(false);
      setNotice('Tournament loaded.');
      setConfirm(null);
    });
  }
  const player =
    tournament && match && match.results.length < 2
      ? tournament.names[match.players[match.results.length] ?? 0]
      : null;
  return (
    <>
      <h2 ref={heading} tabIndex={-1}>
        Tournament
      </h2>
      {!tournament && (
        <section className="tournament-section">
          <div className="tournament-fields">
            <label htmlFor="players">Players</label>
            <select
              className="control"
              id="players"
              value={count}
              onChange={(e) => setCount(Number(e.target.value))}
            >
              <option value={4}>4</option>
              <option value={8}>8</option>
            </select>
          </div>
          <div className="tournament-names">
            {drafts.slice(0, count).map((name, i) => (
              <label key={i}>
                Player {i + 1}
                <input
                  className="control"
                  value={name}
                  onChange={(e) => setDrafts(drafts.map((v, j) => (i === j ? e.target.value : v)))}
                />
              </label>
            ))}
          </div>
          <button className="control" onClick={startTournament}>
            Start tournament
          </button>
          <h3>Past tournaments</h3>
          {unavailable && <p>Progress won't be saved on this device.</p>}
          {past.length === 0 ? (
            <p>No past tournaments.</p>
          ) : (
            <ul>
              {past.map((t, i) => {
                const last = t.matches.at(-1);
                const won = last && winner(last);
                return (
                  <li key={i}>
                    <button
                      className="control"
                      onClick={() => {
                        setTournament(t);
                        setNotice('Tournament loaded.');
                      }}
                    >
                      Champion: {won === null || won === undefined ? '' : t.names[won]}
                    </button>
                  </li>
                );
              })}
            </ul>
          )}
          <button className="control" onClick={back}>
            Back to game
          </button>
        </section>
      )}
      {tournament && (
        <section className="tournament-section">
          {champion !== null && champion !== undefined ? (
            <>
              <p>Champion: {tournament.names[champion]}</p>
              <button className="control" onClick={back}>
                Back to game
              </button>
              <button
                className="control"
                onClick={() => {
                  setTournament(null);
                  setNotice('');
                }}
              >
                Tournament setup
              </button>
            </>
          ) : (
            <>
              <p>Round: {roundName(tournament.names.length, tournament.matches.length - 1)}</p>
              {player && <p>Now playing: {player}</p>}
              {!playing && !handoff && match && match.results.length < 2 && (
                <button className="control" onClick={startTurn}>
                  Start turn
                </button>
              )}
              {!playing && handoff && match?.results.length === 1 && (
                <button
                  className="control"
                  onClick={() => {
                    setHandoff(false);
                    setNotice(`Now playing: ${player}`);
                  }}
                >
                  Next turn
                </button>
              )}
              {!playing && match?.results.length === 2 && (
                <button
                  className="control"
                  onClick={() => {
                    setTournament(makeMatch(tournament));
                    setHandoff(false);
                    setNotice('Next match.');
                  }}
                >
                  Next match
                </button>
              )}
              <button className="control" onClick={() => leaveOr(back)}>
                Leave tournament
              </button>
            </>
          )}
          <Bracket tournament={tournament} />
        </section>
      )}
      {playing && (
        <>
          <GameStatus
            game={game.session.game}
            best={undefined}
            celebration={game.session.celebration}
            hideBest
          />
          <p id="board-help" className="help">
            Use a pointer or Tab to enter the board. Arrow keys move between cards. Enter or Space
            reveals a card.
          </p>
          <Board
            key={game.session.generation}
            game={game.session.game}
            activate={game.activate}
            ref={board}
          />
        </>
      )}
      <div className="game-result">
        <p role="status" aria-live="polite" aria-atomic="true">
          <span key={playing ? game.session.announcement : notice}>
            {playing ? game.session.feedback || notice : notice}
          </span>
        </p>
      </div>
      <section className="tournament-section">
        <label htmlFor="tournament-json">Tournament JSON</label>
        <textarea
          id="tournament-json"
          className="control tournament-json"
          value={json}
          onChange={(e) => setJson(e.target.value)}
        />
        <div className="tournament-actions">
          <button
            className="control"
            onClick={() => {
              setJson(
                encodeExchange({
                  tournament,
                  snapshot: playing ? game.exportGame() : pendingSnapshot,
                }),
              );
              setNotice('Tournament exported.');
            }}
          >
            Export tournament
          </button>
          <button className="control" onClick={load}>
            Load tournament
          </button>
        </div>
      </section>
      {confirm && <LeaveDialog keep={() => setConfirm(null)} leave={confirm} />}
    </>
  );
}

